-- Preenche kind e payload das pendências abertas, pelo título (e pelo cliente quando a resposta é só dele).
-- Seguro de repetir: só mexe em pendências sem kind. Para desfazer tudo:
--   update public.pendencias set kind = null, payload = null, resposta = null;

update public.pendencias set kind = 'choose', payload = '{"pergunta": "Qual é o endereço correto?", "opcoes": [{"valor": "saul-elkind", "rotulo": "Av. Saul Elkind, 1433", "detalhe": "É o que o perfil mostra hoje"}, {"valor": "lago-vitoria", "rotulo": "Rua Lago Vitória, 696", "detalhe": "Estava na descrição antiga"}], "permitir_outro": true}'::jsonb where titulo = 'Endereço em conflito' and kind is null and status in ('aberta', 'aprovada') and cliente_id = (select id from public.clientes where slug = 'clinica-central-norte');
